  <title>Notification Preferences</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f5f7fb;
      --surface: #ffffff;
      --text: #172033;
      --muted: #5e6a7d;
      --primary: #3157d5;
      --primary-dark: #2344aa;
      --border: #d8deea;
      --border-strong: #a9b4c7;
      --success: #176b3a;
      --shadow: 0 24px 60px rgba(28, 39, 63, 0.14);
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      line-height: 1.5;
      color: var(--text);
      background:
        radial-gradient(circle at top left, rgba(49, 87, 213, 0.16), transparent 34rem),
        linear-gradient(135deg, #f8faff 0%, var(--bg) 100%);
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      z-index: 10;
      transform: translateY(-150%);
      padding: 0.75rem 1rem;
      color: #ffffff;
      background: var(--primary);
      border-radius: 0.75rem;
      font-weight: 700;
      text-decoration: none;
    }

    .skip-link:focus {
      transform: translateY(0);
      outline: 3px solid #111827;
      outline-offset: 3px;
    }

    main {
      width: min(100% - 2rem, 760px);
      min-height: 100vh;
      margin: 0 auto;
      display: grid;
      place-items: center;
      padding: 3rem 0;
    }

    .card {
      width: 100%;
      padding: clamp(1.5rem, 5vw, 3rem);
      background: var(--surface);
      border: 1px solid rgba(216, 222, 234, 0.8);
      border-radius: 1.5rem;
      box-shadow: var(--shadow);
    }

    .eyebrow {
      margin: 0 0 0.75rem;
      color: var(--primary);
      font-size: 0.85rem;
      font-weight: 800;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 6vw, 3.25rem);
      line-height: 1.05;
      letter-spacing: -0.04em;
    }

    .intro {
      max-width: 58ch;
      margin: 1rem 0 2rem;
      color: var(--muted);
      font-size: 1.05rem;
    }

    form {
      display: grid;
      gap: 1.5rem;
    }

    .form-field {
      padding: 1.25rem;
      border: 1px solid var(--border);
      border-radius: 1.25rem;
      background: #fbfcff;
    }

    fieldset {
      min-width: 0;
      margin: 0;
      padding: 0;
      border: 0;
    }

    legend {
      padding: 0;
      font-size: 1.125rem;
      font-weight: 800;
    }

    .required-note,
    .field-help {
      margin: 0.35rem 0 0;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .required-marker {
      color: var(--primary-dark);
      font-weight: 900;
    }

    .radio-options {
      display: grid;
      gap: 0.75rem;
      margin-top: 1rem;
    }

    .radio-option {
      display: flex;
      align-items: center;
      gap: 0.8rem;
      min-height: 3.25rem;
      padding: 0.9rem 1rem;
      border: 1px solid var(--border);
      border-radius: 1rem;
      background: #ffffff;
      cursor: pointer;
      transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
    }

    .radio-option:hover {
      border-color: var(--border-strong);
      box-shadow: 0 10px 24px rgba(28, 39, 63, 0.08);
      transform: translateY(-1px);
    }

    input[type="radio"] {
      width: 1.25rem;
      height: 1.25rem;
      margin: 0;
      accent-color: var(--primary);
      flex: 0 0 auto;
    }

    input[type="radio"]:focus-visible {
      outline: 3px solid rgba(49, 87, 213, 0.35);
      outline-offset: 3px;
    }

    .radio-option:has(input[type="radio"]:checked) {
      border-color: var(--primary);
      box-shadow: 0 0 0 4px rgba(49, 87, 213, 0.12);
    }

    .radio-label {
      color: var(--text);
      font-weight: 700;
    }

    button {
      justify-self: start;
      min-height: 3rem;
      padding: 0.85rem 1.35rem;
      color: #ffffff;
      background: var(--primary);
      border: 0;
      border-radius: 999px;
      box-shadow: 0 12px 22px rgba(49, 87, 213, 0.24);
      font: inherit;
      font-weight: 800;
      cursor: pointer;
      transition: background-color 160ms ease, transform 160ms ease;
    }

    button:hover {
      background: var(--primary-dark);
      transform: translateY(-1px);
    }

    button:focus-visible {
      outline: 3px solid rgba(49, 87, 213, 0.35);
      outline-offset: 4px;
    }

    .status {
      min-height: 1.5rem;
      margin: 0;
      color: var(--success);
      font-weight: 700;
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        scroll-behavior: auto !important;
        transition-duration: 0.01ms !important;
      }
    }

    @media (forced-colors: active) {
      .card,
      .form-field,
      .radio-option,
      button {
        border: 1px solid CanvasText;
        box-shadow: none;
      }

      .radio-option:has(input[type="radio"]:checked) {
        outline: 2px solid SelectedItem;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>

  <main id="main-content">
    <section class="card" aria-labelledby="page-title">
      <p class="eyebrow">Preferences</p>
      <h1 id="page-title">Choose your notification channel</h1>
      <p class="intro">Tell us where you want product updates and important account notices to arrive.</p>

      <form id="notification-form">
        <p class="required-note"><span class="required-marker" aria-hidden="true">*</span> Required field</p>

        <div class="form-field">
          <fieldset aria-describedby="notification-help">
            <legend>
              How do you prefer to receive notifications?
              <span class="required-marker" aria-hidden="true">*</span>
            </legend>
            <p id="notification-help" class="field-help">Choose one notification method.</p>

            <div class="radio-options">
              <label class="radio-option" for="notification-email">
                <input id="notification-email" type="radio" name="notification-preference" value="Email" required>
                <span class="radio-label">Email</span>
              </label>

              <label class="radio-option" for="notification-sms">
                <input id="notification-sms" type="radio" name="notification-preference" value="SMS" required>
                <span class="radio-label">SMS</span>
              </label>

              <label class="radio-option" for="notification-push">
                <input id="notification-push" type="radio" name="notification-preference" value="Push Notifications" required>
                <span class="radio-label">Push Notifications</span>
              </label>
            </div>
          </fieldset>
        </div>

        <button type="submit">Save preference</button>
        <p id="form-status" class="status" role="status" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.querySelector("#notification-form");
    const status = document.querySelector("#form-status");

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      if (!form.reportValidity()) {
        status.textContent = "";
        return;
      }

      const selectedPreference = new FormData(form).get("notification-preference");
      status.textContent = `Preference saved: ${selectedPreference}.`;
    });

    form.addEventListener("change", () => {
      status.textContent = "";
    });
  </script>
</body>
</html>
