  <a class="skip-link" href="#main-content">Skip to main content</a>

  <main id="main-content">
    <section class="card" aria-labelledby="page-title">
      <p class="eyebrow">Preferences</p>
      <h1 id="page-title">Choose your notification channel</h1>
      <p class="intro">Tell us where you want product updates and important account notices to arrive.</p>

      <form id="notification-form">
        <p class="required-note"><span class="required-marker" aria-hidden="true">*</span> Required field</p>

        <div class="form-field">
          <fieldset aria-describedby="notification-help">
            <legend>
              How do you prefer to receive notifications?
              <span class="required-marker" aria-hidden="true">*</span>
            </legend>
            <p id="notification-help" class="field-help">Choose one notification method.</p>

            <div class="radio-options">
              <label class="radio-option" for="notification-email">
                <input id="notification-email" type="radio" name="notification-preference" value="Email" required>
                <span class="radio-label">Email</span>
              </label>

              <label class="radio-option" for="notification-sms">
                <input id="notification-sms" type="radio" name="notification-preference" value="SMS" required>
                <span class="radio-label">SMS</span>
              </label>

              <label class="radio-option" for="notification-push">
                <input id="notification-push" type="radio" name="notification-preference" value="Push Notifications" required>
                <span class="radio-label">Push Notifications</span>
              </label>
            </div>
          </fieldset>
        </div>

        <button type="submit">Save preference</button>
        <p id="form-status" class="status" role="status" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.querySelector("#notification-form");
    const status = document.querySelector("#form-status");

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      if (!form.reportValidity()) {
        status.textContent = "";
        return;
      }

      const selectedPreference = new FormData(form).get("notification-preference");
      status.textContent = `Preference saved: ${selectedPreference}.`;
    });

    form.addEventListener("change", () => {
      status.textContent = "";
    });
  </script>
</body>
</html>
